// === Tab: creature ===
class Creature {
	constructor(x, y, s, a) {
		this.x = x;
		this.y = y;
		this.s = s;
		this.a = a;
		this.n = ~~random(3, 8);
		this.clr = color(random(100, 300), random(100, 300), random(100, 300));
		this.speed = random(1, 3);
		this.uid = ~~random(12345);
	}

	update(others) {
		const t = frameCount;
		const len = this.speed * abs(sin(t + this.uid)+2);
		const vec = createVector(len, 0).rotate(this.a);
		let x = this.x + vec.x;
		let y = this.y + vec.y;
		const r = this.s/2;
		if (x < r) {
			x = r;
			vec.x *= -1;
		}
		if (x > width - r) {
			x = width - r;
			vec.x *= -1;
		}
		if (y < r) {
			y = r;
			vec.y *= -1;
		}
		if (y > height - r) {
			y = height - r;
			vec.y *= -1;
		}
		this.x = x;
		this.y = y;
		this.a = vec.heading() + (noise(this.uid, frameCount/100)-0.5)/10;
	}

	draw() {
		var x = this.x;
		var y = this.y;
		const s = this.s;
		const a = this.a;

		push();		
		translate(x, y);
		rotate(a);
		blendMode(BLEND);
		fill(this.clr)
		ellipse(0, 0, s, s/2);

		fill(BG)
		const n = this.n, th = s/n, y1 = -s/4, y2 = s/4;
		for (let i = 0; i <= n; i++) {
			// upper tooth
			const x1 = map(i, 0, n, -s/2, +s/2);
			if (i < n) triangle(
				x1, y1,
				x1+th, y1,
				x1+th*random(0.45, 0.55), y1 + random(0.3, 0.4) * s
			)
			// lower tooth
			const x2 = map(i, 0, n, -s/2, +s/2)-th/2;
			triangle(
				x2, y2,
				x2+th, y2,
				x2+th*random(0.45, 0.55), y2 - random(0.3, 0.4) * s
			)
		} 

		blendMode(DIFFERENCE)
		fill(this.clr)
		ellipse(s/4, 0, s/4, s/3);

		pop()
	}
}

