const NUM = 10;
let creatures;
let FG, BG;

function setup() {
	createCanvas(windowWidth, windowHeight);
	frameRate(15);

	FG = color("navy"); // FG.setAlpha(128);
	BG = color("lightblue")

	let S = max(width, height);
	creatures = [];
	for (let i = 0; i < NUM; i++) {
		const creature = new Creature(
			width  * random(0.3, 0.7), 
			height * random(0.3, 0.7), 
			S * random(0.07, 0.14), 
			random(TAU)
		);
		creatures.push(creature);
	}

	noStroke();
}

function draw() {
	background(BG);

	for (const creature of creatures) {
		creature.update(creatures);
		creature.draw();
	}

	push()
	// blendMode(ADD)
	stroke(FG);
	// for (let y = ~~(frameCount/8) % 8; y < height; y+= 8) line(0, y, width, y);
	pop()
}

function mousePressed() {
	setup();
}
